"""Bind published CPU watcher to the actual new owner, never to stale historical PIDs."""
import base64,hashlib,json,os,subprocess,time
from pathlib import Path
B=Path('/dataset/shaoshitong/recursive-bran-a-h100-20261012/recovery-from100-20261013')
PAYLOAD={'final_eval.py': '', 'boundary_supervisor.py': '', 'final_worker.py': '', 'test_contract.py': ''}
folder=B/'final51713-supervisor-recovery-v1';folder.mkdir(exist_ok=True)
launch=folder/'launch.json';assert not launch.exists(),'Already launched; inspect exact binding'
def process(pid):
 p=Path('/proc')/str(pid);s=(p/'stat').read_text().rsplit(')',1)[1].split();return dict(pid=pid,uid=p.stat().st_uid,tick=int(s[19]))
config=json.loads((B/'receipts/configuration.json').read_text());start=json.loads((B/'receipts/train-start.json').read_text())
assert start['job']=='3393' and start['run_id']==config['run_id']
owner=process(start['pid']);assert owner['uid']==0
retriever=json.loads((B/'retriever/receipts/source-identity.json').read_text());retriever_owner=process(retriever['pid'])
assert retriever_owner['uid']==0
binding=dict(job_id=3393,base=str(B),owner=owner,run_id=config['run_id'],config_sha256=config['config_sha256'],retriever_owner=retriever_owner)
p=folder/'binding.json';p.write_text(json.dumps(binding,indent=2));binding_sha=hashlib.sha256(p.read_bytes()).hexdigest()
manifest={}
for name,data in PAYLOAD.items():
 raw=base64.b64decode(data);dst=folder/name;assert not dst.exists();dst.write_bytes(raw);assert dst.read_bytes()==raw;manifest[name]=hashlib.sha256(raw).hexdigest()
command=['python3','-B','-u',str(folder/'boundary_supervisor.py'),'--control',str(folder),'--binding',str(p),'--binding-sha256',binding_sha]
env=dict(os.environ,CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1');env.pop('LD_LIBRARY_PATH',None)
with (folder/'watcher.log').open('ab') as output:child=subprocess.Popen(command,env=env,stdout=output,stderr=output,start_new_session=True)
time.sleep(1);assert child.poll() is None,(folder/'watcher.log').read_text()
record=dict(time=time.time(),process=process(child.pid),command=command,binding=binding,binding_sha256=binding_sha,payload_manifest=manifest,payload_commit='d40b8a37a9d1658923ff6955579a2ccbd79ff456',phase='CPU_WATCHER_WAITING_NOT_FINAL_SCORING')
launch.write_text(json.dumps(record,indent=2));print(json.dumps(record),flush=True)
